BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO question_seed
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что такое виртуальная память процесса?', '{"A":"Память видеокарты, которую система использует при нехватке оперативной памяти","B":"Собственное адресное пространство процесса: ядро сопоставляет его страницы с физической памятью","C":"Общая для всех процессов память, где они видят данные друг друга","D":"Область диска, куда выгружаются данные при нехватке оперативной памяти"}'::jsonb, 'B', 'Благодаря виртуальной памяти процессы изолированы друг от друга. Ядро решает, откуда взять каждую страницу: выделить новую, прочитать из файла или вернуть из свопа.', '{"A":"К виртуальной памяти процесса память видеокарты отношения не имеет.","B":"Процессор переводит адреса программы в физические по таблицам страниц этого процесса, а ядро ведёт эти таблицы.","C":"У каждого процесса своё адресное пространство; общие участки подключаются только явно.","D":"Это своп. Он лишь одно из мест, где может оказаться страница виртуальной памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Программа одного процесса узнала числовой адрес обычной переменной в другом процессе (общая память специально не организована) и пытается прочитать память по этому адресу у себя. Что произойдёт?', '{"A":"Ядро скопирует нужную страницу из другого процесса","B":"Она прочитает данные, но только если адрес выровнен по границе страницы","C":"Она прочитает данные другого процесса, если оба запущены одним пользователем","D":"Она обратится к своей памяти по этому адресу или получит SIGSEGV, если там ничего нет; данные другого процесса так не прочитать"}'::jsonb, 'D', 'Для обмена данными процессы используют явные механизмы: общую память, каналы, сокеты. Общую память PostgreSQL так и подключает ко всем своим процессам.', '{"A":"Такого автоматического копирования нет.","B":"Выравнивание адреса не даёт доступа к чужому адресному пространству.","C":"Общий пользователь не объединяет адресные пространства: их разделяют таблицы страниц.","D":"Адрес всегда трактуется в адресном пространстве текущего процесса; сам по себе он не даёт доступа к памяти другого процесса."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Какой размер страницы памяти обычно используется в Linux на x86-64?', '{"A":"1 МБ","B":"4 КБ","C":"16 МБ","D":"8 КБ"}'::jsonb, 'B', 'Страница — единица, которой ядро сопоставляет виртуальную память с физической и выгружает её в своп. Страница данных PostgreSQL в 8 КБ — другое понятие с тем же названием.', '{"A":"Обычные страницы памяти намного меньше.","B":"Его показывает команда getconf PAGESIZE. Бывают и большие страницы (huge pages), по 2 МБ.","C":"Это размер сегмента журнала предзаписи PostgreSQL по умолчанию.","D":"Это размер страницы данных PostgreSQL — блока в файлах таблиц, а не страницы памяти ОС."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что обычно хранится в стеке процесса?', '{"A":"Глобальные переменные программы","B":"Адрес возврата из вызванной функции","C":"Машинный код функций","D":"Память, выделенная через malloc","E":"Локальные переменные выполняемых функций"}'::jsonb, 'BE', 'При каждом вызове функции в стеке создаётся кадр: её локальные переменные, сохранённые значения регистров и адрес возврата. При выходе из функции кадр снимается.', '{"A":"Они живут всё время работы программы в области данных.","B":"При вызове функции сохраняется, куда вернуться после её завершения.","C":"Код лежит в отдельной области кода, доступной только для чтения и выполнения.","D":"Её выдаёт распределитель памяти из кучи, а не из стека.","E":"Они лежат в кадре функции и исчезают при выходе из неё."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Где лежат строки переменных окружения сразу после запуска программы в Linux?', '{"A":"В файле /etc/environment, который читается при каждом вызове getenv","B":"В общей памяти, доступной всем процессам","C":"В верхней части начального стека, выше кадров функций: их кладёт ядро при запуске","D":"В куче: их выделяет malloc при старте программы"}'::jsonb, 'C', 'Аргументы и окружение ядро размещает при запуске программы (execve). Исходный блок окружения виден в /proc/PID/environ.', '{"A":"getenv читает из памяти процесса. Файл используется только при входе пользователя в систему.","B":"Окружение у каждого процесса своё: дочерний получает копию.","C":"Ядро копирует их туда вместе с аргументами командной строки при запуске программы (execve), до её первой команды.","D":"Кучи в этот момент ещё нет. В куче оказываются переменные, добавленные позже через setenv."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что верно для значения VmRSS в /proc/PID/status?', '{"A":"Включает страницы процесса, выгруженные в своп","B":"Учитывает и разделяемые страницы, поэтому сумма VmRSS процессов PostgreSQL завышает общий расход памяти","C":"Показывает, сколько адресов процесс зарезервировал","D":"Показывает, сколько памяти процесса сейчас находится в оперативной памяти"}'::jsonb, 'BD', 'VmSize — зарезервированные адреса, VmRSS — страницы в оперативной памяти, VmSwap — выгруженные приватные страницы. Это приближённые показатели: RSS процессов PostgreSQL нельзя просто складывать, а для точного разбора есть /proc/PID/smaps_rollup и показатель PSS, который делит общие страницы между процессами.', '{"A":"Выгруженные приватные страницы показывает отдельное поле VmSwap; своп общей памяти в него не входит.","B":"Общую память каждый процесс учитывает у себя в той мере, в какой к ней обращался.","C":"Это VmSize: зарезервированные адреса, а не занятая оперативная память.","D":"RSS (resident set size) — страницы процесса, присутствующие в RAM."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Процесс обращается к своей странице, которая сейчас выгружена в своп на диске (сжатый кеш zswap не используется). Что произойдёт?', '{"A":"Данные страницы будут потеряны","B":"Ядро сразу завершит процесс через OOM killer","C":"Процесс получит сигнал SIGSEGV","D":"Возникнет страничное прерывание: ядро прочитает страницу с диска, и процесс продолжит работу"}'::jsonb, 'D', 'Чтение страницы из свопа в тысячи раз медленнее обращения к оперативной памяти. Когда таких обращений много, процессы почти всё время ждут диска, и тормозит весь сервер.', '{"A":"Своп для того и нужен, чтобы сохранить содержимое страницы.","B":"OOM killer срабатывает при нехватке памяти, а не при чтении страницы из свопа.","C":"SIGSEGV бывает при обращении к адресу, где ничего нет, а выгруженная страница процессу принадлежит.","D":"Пока страница читается, процесс ждёт диска; в ps он виден в состоянии D."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что не так в этой функции?
```
int *make(void)
{
    int x = 42;
    return &x;
}
```', '{"A":"Переменная x попадёт в кучу и никогда не освободится","B":"Возвращается адрес локальной переменной: после выхода из функции её кадр в стеке уже освобождён","C":"Такой код не скомпилируется","D":"Ничего: x существует до конца работы программы"}'::jsonb, 'B', 'Чтобы вернуть данные из функции, их размещают в куче (malloc, а освобождает вызывающий), в статической переменной или в буфере, который передал вызывающий.', '{"A":"Локальная переменная лежит в стеке, а не в куче.","B":"Указатель становится «висячим»: эту память перезапишет следующий вызов функции.","C":"Код компилируется, обычно с предупреждением; ошибка проявится во время выполнения.","D":"Так было бы для глобальной или статической (static) переменной."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Допишите код, чтобы вернуть память, выделенную через malloc:
```
char *buf = malloc(1024);
/* ... работа с buf ... */
___(buf);
```', '{"A":"`malloc`","B":"`delete`","C":"`free`","D":"`release`"}'::jsonb, 'C', 'Каждому успешному malloc должен соответствовать ровно один free. Если забыть free, будет утечка памяти; если вызвать дважды — неопределённое поведение.', '{"A":"malloc принимает размер, а здесь передаётся указатель: такой вызов ошибочен и блок не освобождает.","B":"Это оператор C++, в C его нет.","C":"Возвращает блок распределителю памяти.","D":"Такой функции в стандартной библиотеке C нет."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Функцию вызывают миллион раз в долго работающем процессе. Программа собрана без оптимизации (-O0), все вызовы malloc успешны. Что произойдёт с его памятью?
```
void handle(void)
{
    char *tmp = malloc(1000);
    strcpy(tmp, "запрос");
}
```', '{"A":"Блок освободится автоматически при выходе из функции","B":"Переполнится стек","C":"После каждого вызова в куче останется блок, на который больше нет указателя: память процесса будет расти","D":"Ничего: ядро само освобождает блоки, на которые нет указателей"}'::jsonb, 'C', 'В долго работающих серверах утечки накапливаются. PostgreSQL выделяет память в контекстах и освобождает её разом при сбросе или удалении контекста: контексты выполнения запроса обычно очищаются по его завершении, а контексты транзакции и сеанса живут дольше.', '{"A":"Автоматически освобождается только стек. В C нет сборщика мусора.","B":"malloc берёт память в куче, стек от этого не растёт.","C":"Указатель tmp исчез вместе с кадром функции, а блок в куче остался — это утечка.","D":"Ядро не следит за указателями программы; всю память процесса оно освобождает только при его завершении."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Программу собрали без оптимизации (cc -O0), лимит стека — 8 МБ. Что произойдёт при вызове f(0)?
```
void f(long n)
{
    char buf[1024];
    buf[0] = (char) n;
    f(n + 1);
}
```', '{"A":"Программа будет работать бесконечно","B":"malloc вернёт NULL","C":"Меньше чем через 8 тысяч вызовов стек закончится, и процесс получит сигнал SIGSEGV","D":"Ядро увеличит стек до размера оперативной памяти"}'::jsonb, 'C', 'Глубина рекурсии ограничена размером стека: размер кадра, умноженный на число вызовов, не может превысить лимит. С оптимизацией компилятор мог бы превратить такую рекурсию в цикл, поэтому опыт ставят с -O0.', '{"A":"Каждый вызов оставляет в стеке новый кадр, и они копятся.","B":"malloc здесь не вызывается: массив buf лежит в стеке.","C":"Каждый кадр занимает больше 1 КБ, а весь стек — 8 МБ.","D":"Стек растёт только до лимита ulimit -s (RLIMIT_STACK)."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Какие утверждения о стеке и куче верны?', '{"A":"Память стека освобождается автоматически при выходе из функции","B":"Все потоки процесса используют один общий стек","C":"malloc выделяет память в кадре стека вызывающей функции","D":"Блок из кучи существует, пока его не освободят вызовом free","E":"Куча обычно меньше стека"}'::jsonb, 'AD', 'Главное различие — время жизни: стек живёт вместе с вызовом функции, куча — пока программа сама не освободит память.', '{"A":"Кадр функции снимается вместе с её локальными переменными.","B":"У каждого потока свой стек, а куча у потоков общая.","C":"malloc выдаёт память из кучи; в стеке выделяет нестандартная функция alloca.","D":"Время жизни блока в куче определяет программа.","E":"Наоборот: стек обычно ограничен 8 МБ, а куча может расти до пределов доступной памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Программа печатает адреса строки исходного окружения, локальной переменной main, небольшого блока из malloc, глобальной переменной и функции main. В каком порядке они обычно идут в Linux на x86-64 при обычной сборке, от больших адресов к меньшим?', '{"A":"Стек, окружение, куча, код, данные","B":"Код, данные, куча, стек, окружение","C":"Куча, стек, окружение, данные, код","D":"Окружение, стек, куча, данные, код","E":"Порядок каждый раз случайный"}'::jsonb, 'D', 'Стек растёт вниз от верхней части адресного пространства, куча — вверх от области данных. Между ними — свободное пространство и отображения библиотек и файлов; туда же попадают крупные блоки malloc, а переменные, добавленные через setenv, — в кучу. Адреса при каждом запуске перемешиваются ради защиты (ASLR), но типичный порядок сохраняется.', '{"A":"Исходное окружение лежит в верхней части начального стека, выше текущих кадров функций; данные обычно расположены выше кода.","B":"Это порядок от меньших адресов к большим.","C":"Куча расположена ниже стека.","D":"Исходное окружение лежит в верхней части начального стека, выше кадров функций; небольшие блоки malloc берутся из кучи, растущей вверх от области данных; код ниже всего.","E":"Случайны конкретные адреса, а взаимный порядок областей при обычной сборке сохраняется."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Допишите команду оболочки, чтобы узнать лимит размера стека для запускаемых процессов (в килобайтах):
```
ulimit ___
```', '{"A":"`-v`","B":"`-s`","C":"`-n`","D":"`-c`"}'::jsonb, 'B', 'Лимит действует на процессы, запущенные из этой оболочки. Для служб systemd его задаёт параметр LimitSTACK. С этим лимитом PostgreSQL сверяет max_stack_depth.', '{"A":"Это лимит виртуальной памяти процесса.","B":"Показывает лимит стека; обычно 8192 КБ.","C":"Это лимит числа открытых файлов.","D":"Это лимит размера файла дампа памяти (core)."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Функция печатает адрес своей локальной переменной и вызывает саму себя ещё дважды. Что верно для трёх напечатанных адресов?
```
void show(int level)
{
    int local = level;
    printf("%d: %p\n", level, (void *) &local);
    if (level < 3)
        show(level + 1);
}
```', '{"A":"Адреса разные: у каждого вызова свой кадр со своей переменной local","B":"Адреса одинаковые: переменная local одна на все вызовы","C":"Обычно каждый следующий адрес меньше предыдущего","D":"Адреса лежат в куче"}'::jsonb, 'AC', 'Именно потому, что у каждого вызова свой кадр, рекурсия работает: значения переменных одного вызова не затирают значения другого.', '{"A":"Каждый вызов функции создаёт в стеке новый кадр.","B":"Так было бы для статической переменной, а обычная локальная создаётся заново при каждом вызове.","C":"В Linux на x86-64 стек растёт в сторону меньших адресов.","D":"Локальные переменные находятся в стеке."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что произойдёт при выполнении этого кода?
```
char *p = malloc(16);
free(p);
free(p);
```', '{"A":"Второй вызов free просто игнорируется","B":"Код не скомпилируется","C":"Освободятся 32 байта: по 16 за каждый вызов","D":"Неопределённое поведение: обычно распределитель памяти замечает повторное освобождение и аварийно завершает процесс"}'::jsonb, 'D', 'После free указатель полезно обнулять: вызов free(NULL) безопасен и ничего не делает.', '{"A":"Стандарт этого не гарантирует: повторное освобождение — ошибка программы.","B":"Компилятор такую ошибку обычно не обнаруживает: она проявляется во время работы.","C":"Блок один, освободить его можно только один раз.","D":"Например, glibc сообщает «double free detected» и завершает процесс сигналом SIGABRT."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Почему вызов malloc на 1 ГБ может завершиться успешно, хотя свободной оперативной памяти меньше?', '{"A":"Программа получает часть памяти видеокарты","B":"malloc сжимает данные","C":"malloc сразу записывает выделенную память в своп","D":"Ядро сначала выдаёт только адреса, а страницы оперативной памяти обычно выделяет при первой записи в них"}'::jsonb, 'D', 'Поэтому RSS не вырастает сразу на весь запрошенный объём, а растёт по мере записи. Обратная сторона: если страниц потом не хватит, ядро может запустить OOM killer.', '{"A":"Распределитель памяти так не работает.","B":"Распределитель памяти данные не сжимает.","C":"Память без записанных данных никуда не пишется.","D":"Это выделение по требованию. Допустимость новых обязательств по памяти определяет режим overcommit (vm.overcommit_memory) — отдельный механизм."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что верно для механизма OOM killer в Linux?', '{"A":"При нехватке памяти ядро выбирает процесс-жертву с учётом занятой памяти и поправки oom_score_adj и завершает его сигналом SIGKILL","B":"OOM killer выгружает в своп все процессы","C":"Если OOM killer завершит обслуживающий процесс PostgreSQL, postmaster перезапустит все процессы с восстановлением после сбоя","D":"OOM killer перезагружает сервер"}'::jsonb, 'AC', 'Документация PostgreSQL советует на выделенном сервере БД ставить vm.overcommit_memory = 2 и защищать postmaster через oom_score_adj, чтобы OOM killer не выбрал его.', '{"A":"Если памяти не хватило внутри cgroup, например в службе с MemoryMax, жертва выбирается только среди процессов этой группы.","B":"Выгрузкой в своп занимается механизм управления памятью, а OOM killer завершает процессы.","C":"Аварийно завершённый процесс мог повредить общую память, поэтому сервер переинициализируется.","D":"Он завершает отдельный процесс, а не весь сервер."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'У службы systemd заданы MemoryHigh=1700M и MemoryMax=2G, своп для неё не ограничен. Процессу службы нужно 3,6 ГБ. Что произойдёт?', '{"A":"Процесс сразу будет завершён по лимиту MemoryMax","B":"Процесс может работать днями почти без продвижения и при этом нагружать диск","C":"Выше 1700 МБ ядро будет притормаживать процесс и принудительно освобождать его память, в том числе вытеснять страницы в своп, если есть подходящие страницы и место","D":"Служба будет перезапускаться каждый раз, как процесс займёт 2 ГБ"}'::jsonb, 'BC', 'В cgroup v2 своп учитывается отдельно (MemorySwapMax), а MemoryHigh лишь тормозит процесс. Пока своп службы не ограничен, процесс, которому не хватает памяти, может надолго нагрузить диск и замедлить весь сервер.', '{"A":"Не сразу: сначала ядро пытается освободить память, в том числе вытеснением в своп. Жёсткий лимит и OOM возможны позже, если освободить память не удаётся.","B":"Страницы постоянно ходят между памятью и свопом, а процесс почти всё время ждёт.","C":"MemoryHigh — мягкий порог: при его превышении процесс не завершается, а замедляется.","D":"Мгновенного перезапуска нет: сначала срабатывают мягкий порог и освобождение памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Какие настройки службы systemd ограничат её оперативную память 2 ГБ и запретят ей своп, чтобы нехватка памяти не превращалась в долгое торможение в свопе?', '{"A":"MemoryMax=2G и MemorySwapMax=0, без MemoryHigh ниже MemoryMax","B":"MemoryHigh=1700M без MemoryMax","C":"MemoryMax=2G и MemorySwapMax=infinity","D":"CPUQuota=50%"}'::jsonb, 'A', 'Настройки запрещают своп этой службе; если освободить память не удаётся, возможен OOM внутри её группы. Какой процесс станет жертвой и как быстро, не гарантируется. OOMPolicy=continue не даёт systemd остановить всю службу из-за самого OOM-события, но не спасает, если завершён её главный процесс.', '{"A":"Если освободить память внутри службы не удастся, ядро запустит OOM в её группе. Какой процесс станет жертвой и как быстро, не гарантируется.","B":"Мягкий порог только тормозит процесс, а без жёсткого лимита процесс может занять и больше.","C":"Своп службе разрешён, поэтому эти настройки не выполняют требование запретить своп.","D":"Это ограничение процессора, а не памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что верно для памяти дочернего процесса, созданного вызовом fork() в Linux?', '{"A":"Вся память родителя сразу копируется в момент fork","B":"Изменения, которые делает потомок, видны родителю","C":"Дочерний процесс получает копию адресного пространства родителя","D":"Дочерний процесс начинает работу с пустой памятью","E":"Страницы физически копируются только при записи в них (копирование при записи)"}'::jsonb, 'CE', 'Поэтому fork быстрый даже у процесса с большой памятью. PostgreSQL в Linux порождает обслуживающие процессы через fork от postmaster: они сразу получают загруженный код и настройки.', '{"A":"Это было бы медленно; копирование откладывается до первой записи.","B":"После записи у каждого своя копия страницы; видны только участки, явно подключённые как общая память.","C":"В нём те же код, данные, куча и стек, что у родителя в момент fork.","D":"С новой памятью начинает программа, запущенная через execve, а не fork.","E":"До первой записи родитель и потомок пользуются одними физическими страницами."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Команда free -m вывела на сервере такие строки. Сколько оперативной памяти примерно доступно новым программам без вытеснения в своп?
```
               total   used   free  shared  buff/cache  available
Mem:            3915   3623    259     167        434        291
Swap:           2047    111   1936
```', '{"A":"434 МБ: столбец buff/cache","B":"Около 291 МБ: столбец available","C":"259 МБ: столбец free","D":"1936 МБ: свободный своп"}'::jsonb, 'B', 'Для оценки свободной памяти смотрят столбец available. Если он мал, а своп растёт, сервер вот-вот начнёт тормозить из-за обращений к диску.', '{"A":"Кеш нельзя освободить целиком: часть его используется.","B":"Это оценка ядра с учётом кеша файлов, который можно освободить.","C":"Это совсем незанятая память; часть кеша тоже можно освободить, поэтому доступно немного больше.","D":"Своп — место на диске, а не оперативная память."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Допишите команду, чтобы узнать, сколько приватной памяти процесса с PID 1234 сейчас выгружено в своп:
```
grep ___ /proc/1234/status
```', '{"A":"`SwapTotal`","B":"`VmSwap`","C":"`VmSize`","D":"`VmRSS`"}'::jsonb, 'B', 'VmRSS и VmSwap — быстрые приближённые показатели. Для подробного разбора памяти процесса есть /proc/PID/smaps_rollup, где показатель PSS делит общие страницы между процессами.', '{"A":"Это поле /proc/meminfo: общий размер свопа системы, а не процесса.","B":"Показывает объём приватных страниц процесса в свопе; своп общей памяти сюда не входит.","C":"Это зарезервированные адреса, а не память в свопе.","D":"Это страницы процесса в оперативной памяти."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Что находится в общей памяти PostgreSQL, доступной всем процессам сервера?', '{"A":"Таблица блокировок","B":"Кеш системного каталога","C":"Буферный кеш (shared_buffers)","D":"Буферы журнала предзаписи и статусов транзакций","E":"Память для сортировки в пределах work_mem"}'::jsonb, 'ACD', 'Основная общая область с shared_buffers создаётся при запуске сервера и подключается ко всем его процессам; дополнительные сегменты динамической общей памяти могут выделяться во время работы, например для параллельных запросов. Локальная память у каждого обслуживающего процесса своя и выделяется по мере надобности.', '{"A":"Иначе процессы не могли бы проверять конфликты блокировок друг друга.","B":"Каждый процесс хранит нужную ему часть каталога в своей локальной памяти.","C":"Страницы таблиц и индексов кешируются один раз для всех процессов.","D":"Их используют все процессы, которые меняют данные.","E":"Она выделяется в локальной памяти обслуживающего процесса, выполняющего запрос."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Параметр work_mem = 64MB. В непараллельном плане запроса две сортировки и одно хеш-соединение, hash_mem_multiplier по умолчанию. Сколько памяти могут занять эти операции?', '{"A":"Больше 64 МБ: лимит действует на каждую операцию, а для хеш-операций умножается на hash_mem_multiplier","B":"64 МБ на весь сервер","C":"Ровно 64 МБ на весь запрос","D":"64 МБ на каждый сеанс независимо от плана"}'::jsonb, 'A', 'work_mem умножается на число операций в плане, на число параллельных процессов и на число одновременных запросов. Слишком большое значение при многих подключениях может увести сервер в своп или под OOM killer.', '{"A":"Здесь бюджеты операций — до 64 + 64 + 128 МБ (hash_mem_multiplier по умолчанию равен 2). Это не жёсткий предел всей памяти запроса: есть и другие расходы.","B":"Общий объём памяти сервера задаёт не work_mem; например, shared_buffers — размер буферного кеша.","C":"work_mem ограничивает отдельную операцию сортировки или хеширования, а не весь запрос.","D":"Сеанс с несколькими операциями в плане может занять больше."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Лимит стека в системе — 8192 КБ (ulimit -s). Какое значение max_stack_depth — наибольшее разумное?', '{"A":"2MB","B":"8MB","C":"7MB: лимит ядра за вычетом запаса около мегабайта","D":"0","E":"64MB"}'::jsonb, 'C', 'max_stack_depth задаёт, на какой глубине PostgreSQL сам прервёт запрос с ошибкой «stack depth limit exceeded». Если он больше реального стека, процесс может упасть по SIGSEGV, и postmaster перезапустит все процессы.', '{"A":"Это значение по умолчанию: оно безопасно, но с большим запасом.","B":"Без запаса сервер это значение не примет: оно больше лимита ядра за вычетом 512 КБ.","C":"Так советует документация: процесс должен заметить переполнение раньше, чем стек действительно кончится.","D":"Такое значение недопустимо: минимальное значение параметра — 100 КБ.","E":"Значение больше лимита ядра сервер отвергнет и подскажет увеличить ulimit -s."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'В Linux postmaster породил обслуживающий процесс для нового клиента вызовом fork. Что верно для памяти этого процесса сразу после fork?', '{"A":"Изменения его локальных переменных и кучи видны postmaster","B":"В его памяти уже есть код и прочитанные postmaster настройки; приватные страницы физически разделяются с postmaster до первой записи, а разделяемые отображения остаются общими","C":"postmaster заново запускает программу postgres через exec и передаёт ей настройки","D":"Общая память, включая буферный кеш, — одна и та же для postmaster и всех обслуживающих процессов"}'::jsonb, 'BD', 'Каждое подключение — отдельный процесс. Копирование при записи делает его создание быстрым, но по мере работы процесс заполняет свою локальную память: кеш каталога, память для сортировок, разобранные запросы.', '{"A":"После записи у обслуживающего процесса своя копия страницы; postmaster её не видит.","B":"Так работает копирование при записи для приватных страниц: копия появляется, только когда один из процессов в страницу пишет.","C":"В Windows PostgreSQL запускает новый процесс через CreateProcess и передаёт ему нужные параметры; в Linux новый процесс получает копию памяти postmaster через fork.","D":"Общая память подключена как разделяемая: после fork её страницы остаются общими, и изменения видны всем процессам."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Почему пароль для подключения лучше хранить в ~/.pgpass, а не в переменной окружения PGPASSWORD?', '{"A":"libpq не читает переменную PGPASSWORD","B":"Окружение процесса доступно через /proc/PID/environ его владельцу и root, а в некоторых системах и другим пользователям через ps","C":"PGPASSWORD хранится в общей памяти сервера PostgreSQL","D":"Экспортированную переменную наследуют дочерние процессы: пароль получат все команды, запущенные из этой оболочки"}'::jsonb, 'BD', 'Файл .pgpass с правами 0600 доступен только владельцу, и libpq читает его лишь при подключении. Пароль не остаётся в окружении процессов.', '{"A":"Читает: она действует как параметр подключения password.","B":"Поэтому документация не рекомендует PGPASSWORD из соображений безопасности.","C":"Это переменная окружения клиента, к памяти сервера она отношения не имеет.","D":"Окружение копируется при fork и передаётся при execve. Если задать переменную только для одной команды, её получит этот процесс и его потомки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Почему в /proc/PID/environ обслуживающего процесса PostgreSQL в Linux вместо исходного окружения могут быть видны обрывки строки вида «postgres: student appdb idle»?', '{"A":"Окружение зашифровано ради безопасности","B":"Ядро очищает окружение после fork","C":"Обслуживающие процессы запускаются без окружения","D":"PostgreSQL перезаписывает область аргументов, чтобы показывать в ps своё состояние, а окружение при старте заранее переносит в кучу"}'::jsonb, 'D', '/proc/PID/environ показывает исходную область окружения. У процессов PostgreSQL её может занимать строка состояния, которую видно в ps, а действующее окружение скопировано в кучу.', '{"A":"Шифрования окружения нет: исходная область просто перезаписана строкой состояния.","B":"fork сохраняет копию окружения в дочернем процессе.","C":"Они наследуют окружение postmaster через fork.","D":"Строки окружения идут сразу за аргументами, поэтому их копируют в кучу. В исходной области могут оказаться часть строки состояния или нулевые байты."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '18.'), 'Допишите команду, чтобы узнать размер общего буферного кеша сервера:
```
SHOW ___;
```', '{"A":"`work_mem`","B":"`buffer_cache`","C":"`effective_cache_size`","D":"`shared_buffers`"}'::jsonb, 'D', 'shared_buffers выделяется в общей памяти при запуске сервера; его изменение требует перезапуска.', '{"A":"Это лимит локальной памяти на одну операцию сортировки или хеширования.","B":"Такого параметра нет.","C":"Это оценка для планировщика: память по нему не выделяется.","D":"Буферный кеш в общей памяти, общий для всех процессов."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 30 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
